def make_emotions_words():
    words = []
    subs = ["emotions_positive", "emotions_negative", "emotions_traits", "emotions_mind", "emotions_communication"]
    for i, w in enumerate(emotions_data):
        sub = subs[i // 50]
        words.append((w[0], w[1], w[2], f"[{w[0].lower()}]", w[3], w[4], w[5], w[6], "emotions", sub, w[7]))
    return words

EMOTIONS_WORDS = make_emotions_words()
